const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function sourcesHTML(catalog,events,lang){
 const t=(zh,en)=>lang==='en'?en:zh,m=catalog.metadata;
 const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
 const stats=[['13,380',t('疆域时段记录','Territory time records')],['11,328',t('历史聚落与地名','Historical place records')],['10,350',t('离散人口观测','Population observations')],[String(events.length),t('双语精选事件','Bilingual curated events')]];
 const sources=[
 [t('历史疆域','Historical territories'),'Cliopatria · Seshat Global History Databank',m.repository,'CC BY 4.0'],
 [t('陆地、河流、湖泊、晕渲','Land, rivers, lakes & relief'),'Natural Earth','https://www.naturalearthdata.com/about/terms-of-use/','Public domain'],
 [t('在线精细高程','Fine elevation on demand'),'Mapterhorn','https://mapterhorn.com/attribution/',t('各地区上游许可与署名','Regional upstream licenses & attribution')],
 [t('古代地名与遗址','Ancient places & sites'),'Pleiades','https://pleiades.stoa.org/downloads','CC BY 3.0'],
 [t('城市人口研究','Historical urban populations'),'Reba, Reitsma & Seto (2016)','https://doi.org/10.1038/sdata.2016.34','CC BY 4.0'],
 [t('首都关系、国家档案、双语名称','Capital relationships, dossiers & labels'),'Wikidata','https://www.wikidata.org/wiki/Wikidata:Licensing','CC0'],
 [t('在线海岸、水系与现代参照','Online coasts, waterways & modern reference'),'OpenFreeMap / OpenMapTiles / OpenStreetMap','https://www.openstreetmap.org/copyright','ODbL · OpenStreetMap contributors'],
 [t('地图引擎','Map engine'),'MapLibre GL JS 5.6.2','https://github.com/maplibre/maplibre-gl-js','BSD-3-Clause']
 ];
 return `<span class="eyebrow">EVIDENCE & CARTOGRAPHY</span><h1>${t('每一条线，都有来处','Every line has a source')}</h1><p class="lead">${t('历史的细节来自资料，地图的层次来自山川。这里记录所用档案、绘图方法与年代约定，也保留尚待研究的空白。','Historical detail comes from evidence; geographic depth comes from the land. This page records our archives, mapmaking methods and dating conventions, including the questions still open.')}</p>
 <div class="stat-grid">${stats.map(([n,label])=>`<div class="stat-card"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div>
 <div class="sources-actions"><button id="downloadEvents">${t('导出事件','Export events')}</button><button id="downloadCatalog">${t('导出疆域目录','Export territory catalog')}</button><button id="downloadCoverage">${t('导出覆盖报告','Export coverage report')}</button></div>
 <section class="method-section"><h2>${t('三种精度，各有所指','Three kinds of precision')}</h2><p>${t('底图细节、历史证据与绘制保真度是三个层面。疆域时段覆盖公元前3400年至2024年，精细层保留固定版本的原始坐标、环与部件顺序；地图没有人为补造曲线。常用年份直接读取原始几何，其他年份先显示快速概览，再按需补齐。13条上游几何问题保留在资料注记中。','Basemap detail, historical evidence and rendering fidelity are distinct. Territory periods span 3400 BCE–2024 CE. The fine layer preserves coordinates, rings and component order from the pinned source, without invented border curves. Common years load original geometry immediately; other years start with an overview and then gain detail. Thirteen upstream geometry issues remain documented.')}</p><p>${t('自然底图采用Natural Earth 1:1000万陆地与水系、真实晕渲；放大时加载Mapterhorn高程。10m在Natural Earth中指地图比例尺，不是10米定位精度。现今地形、海岸与河流为历史阅读提供地理参照，古海岸和河道演变需要另据研究。默认水系排除数据中明确标记的现代水库和运河。','The physical base uses Natural Earth 1:10 million land and waterways with real shaded relief, supplemented by Mapterhorn elevation as you zoom. Natural Earth’s 10m denotes map scale, not ten-metre positional accuracy. Contemporary landforms, coasts and rivers provide geographic context; their historical evolution requires separate evidence. Waterways explicitly marked as modern reservoirs or canals are excluded by default.')}</p><p>${t('“自然海岸对齐”以现今陆地轮廓遮去伸入海面的粗略疆域包络，使山川与国境在视觉上衔接。关闭该图层可查看原始范围。它是显示方式，不修改疆域数据，也不构成古代海岸重建。全球视角先载入轻量概览，区域视角再补全精细岸线与水系，近距离自动读取OpenFreeMap的海洋轮廓与精细河流中心线，默认排除运河和排水沟类别。现代道路、建筑和城市仍由“现代地理参照”单独开启。','Align to natural coasts masks rough territory envelopes extending into the present-day sea. Turn it off to inspect the original extents. This is a display convention: it changes neither the archived geometry nor our knowledge of ancient coasts. The world view starts with a light overview, with fine coasts and waterways at regional scale and OpenFreeMap ocean outlines and fine river centerlines at close zoom, excluding canal and drain classes by default. Contemporary roads, buildings and cities remain a separate opt-in layer.')}</p><p>${t('前1年直接接公元1年，没有公元0年。疆域记录的起止年均包含在有效区间中，区间内部不做虚构插值。地图留白表示这份资料没有该位置和年份的记录。','1 BCE is followed by 1 CE, without year zero. Territory intervals include both endpoints and are not interpolated. Blank map areas indicate that this archive has no record for that place and year.')}</p></section>
 <section class="method-section"><h2>${t('城市的年代怎样读','Reading the dates of places')}</h2><p>${t('Pleiades提供11,328条历史地名：10,656条有明确位置与时期，另672条使用有年代的名称和来源代表点。各个文化时期分别保存，空白时段保持空白；代表点的定位误差记为未知。地点档案保留贡献者、原名与来源。','Pleiades contributes 11,328 historical place records: 10,656 with explicit locations and periods, plus 672 using dated names and source representative points. Discrete cultural periods remain separate, with gaps preserved. Representative points retain unknown positional accuracy. Place records keep contributors, original names and sources.')}</p><p>${t('城市人口资料含2,043条来源城市记录、10,350次观测，时间从公元前3700年至2000年。地图可显示所选年附近50年内的观测，并明确标出实际年份。记录采用原研究地名，常为现代名称；人口数值按各研究对城市范围和估计方法的定义阅读。同名城市的不同来源不会合计成一个人口值。','Population studies contain 2,043 source city records and 10,350 observations from 3700 BCE to 2000 CE. The map can show observations within 50 years of the selected date, explicitly labeled with their actual year. Names follow the studies, often using contemporary place names. Population estimates retain each study’s urban extent and method; different sources for one city are never summed.')}</p><p>${t('首都层保留307条明确时段的维基数据关系，涉及249城，其中24条有非导入来源引证。首都时段、人口观测、文化期都按各自含义展示，不能当作城市建造和废弃日期。可选的现代参照另外提供7,342个现代城市，以及在线的现今水道、道路与建筑。','The capital layer contains 307 explicitly dated Wikidata relationships for 249 cities, including 24 with non-import references. Capital tenures, population observations and cultural periods keep their distinct meanings; none is treated as a city’s foundation or abandonment date. Optional modern reference provides 7,342 contemporary cities plus online current waterways, roads and buildings.')}</p></section>
 <section class="method-section"><h2>${t('档案、叙事与双语','Dossiers, narrative & language')}</h2><p>${t('国家阅读包含1,450份实体档案，关联1,579个疆域源名称；330份档案含1,885项带引证声明。另有23篇依据博物馆、联合国教科文组织等资料编写的双语文明概览、47条侧记和12条专题路线。新增12篇重要城市的双语篇章，按39条明确记录绑定，参考39份机构资料。资料密度因地区、时期而异。','Polity reading includes 1,450 entity dossiers associated with 1,579 source territory names; 330 dossiers include 1,885 cited statements. It also offers 23 bilingual civilization overviews drawing on museum, UNESCO and other sources, 47 historical highlights and 12 thematic journeys. Twelve city chapters link to 39 identified place records and draw on 39 institutional references. Coverage varies by region and period.')}</p><p>${t('档案按声明自带年代筛选；无年代条目作为实体概况，无引证条目收在折叠补充资料中。880条可能的跨源年代关联冲突已标记，相关实体补充资料暂不展示。联盟等385条RELATION记录保留在目录里，避免与成员疆域重叠涂色。','Dossiers respect dates attached to individual statements. Undated facts describe the entity generally, while unreferenced claims stay in a collapsed supplement. The 880 potential cross-source chronological conflicts are flagged and their entity supplements withheld. The 385 RELATION records remain in the catalog without being painted over member territories.')}</p><p>${t('界面、事件与结构化说明提供简体中文和英文。可靠中文地名来自已核对标签或编辑映射；缺少译名时保留来源原文。地名库引文保持原语言。事件为来源导向的编辑摘要，部分参考网页有访问限制，未逐条完成全文核验，也尚未经过历史学家逐项审稿。','The interface, events and structured descriptions offer Simplified Chinese and English. Chinese place labels follow checked sources or editorial mappings; untranslated names remain in the source language. Gazetteer excerpts retain their original language. Events are source-guided editorial summaries: access restrictions prevented full-text verification of every reference, and they have not yet undergone individual historian review.')}</p></section>
 <section class="method-section"><h2>${t('加载、联网与恢复','Loading, connectivity & recovery')}</h2><p>${t('完整下载包内含疆域、全球晕渲、海岸水系、城市与阅读档案，按需加载。在线精细高程及现代矢量参照由外部服务提供；服务暂不可用时保留本地底图，图层面板提供重试。已下载文件需要通过本地服务器打开，不能直接双击HTML。','The full download includes territory geometry, global relief, coasts, waterways, places and reading archives, loaded on demand. Fine elevation and modern vector references use external services. If those services fail, the local map remains available, with retry in the layer panel. Run the downloaded site through its local server rather than opening the HTML file directly.')}</p></section>
 <section class="method-section"><h2>${t('来源、版本与许可','Sources, versions & licenses')}</h2><div class="table-scroll"><table><thead><tr><th>${t('内容','Content')}</th><th>${t('来源','Source')}</th><th>${t('许可','License')}</th></tr></thead><tbody>${sources.map(([a,b,c,d])=>`<tr><td>${a}</td><td>${link(c,b)}</td><td>${d}</td></tr>`).join('')}</tbody></table></div><p>${t('原创双语事件摘要采用CC BY 4.0。地形、城市与几何的转换记录、固定版本、哈希与许可清单均随项目保存。','Original bilingual event summaries use CC BY 4.0. Transformation records, pinned versions, hashes and license manifests for terrain, places and geometry ship with the project.')}</p><p>${link(m.sourceDownloadUrl,t('固定版本疆域原始数据','Pinned original territory dataset'))}<br><small>${esc(m.commit)}<br>SHA256 ${esc(m.sourceZipSha256)}</small></p></section>
 <section class="method-section"><h2>${t('互相参照的历史图集','Complementary historical atlases')}</h2><p>${t('交互设计参考这些项目，各份上游数据按独立许可接入。专业图集的数据库、日级历史和街区复原仍各有长处；经纬纪继续按地区、年代与主题补充可核查资料。','These projects inform our interaction design; upstream datasets are integrated under their own licenses. Specialist archives, daily chronology and street-level reconstruction retain distinct strengths. Meridian continues to expand verifiable coverage across regions, periods and themes.')}</p>${[['Chronosphere','https://worldbyyear.com/'],['Phersu Atlas','https://www.phersu-atlas.com/'],['Running Reality','https://www.runningreality.org/'],['OpenHistoricalMap','https://www.openhistoricalmap.org/'],['HistoryMaps','https://history-maps.com/timeline']].map(([name,url])=>`<p>${link(url,name)}</p>`).join('')}</section>`;
}
